message:
Create a concise read-only comparison-review interface. Show process status, backend diagnostic reasons, and the exact outputs and checks. Use two useful sections from the public kit. This is an isolated synthetic process for SDK qualification; no engineering acceptance or operations are requested. Return exactly source and manifest as JSON. Preserve the supplied manifest exactly, including its process and capabilities; no new bindings. Default export App with the supplied AppProps. Use ?? [] for optional arrays.
{"manifest": {"schema_version": "wright.process-ui/1", "ui_id": "comparison-ui", "revision_id": "revision-one", "parent_revision": null, "title": "Comparison review", "process": {"workspace_id": "synthetic-ui-model-test", "source_path": "workflows/synthetic-comparison.wflow", "source_digest": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa", "semantic_digest": null, "source_contract": "canonical-source"}, "interaction_version": "wright.process-interaction/1", "client_version": "1.0.0", "kit_version": "1.0.0", "bindings": [], "capabilities": ["process.read", "process.results", "process.navigate"], "navigation": [], "viewers": []}, "reference": "import type { InteractionSnapshot, ProcessClient } from '@wright/process-client';
import { ProcessUI, Section, ProgressPanel, ResultCard, ReasonNotice } from '@wright/ui-kit';

export interface AppProps {
  client: ProcessClient;
  snapshot: InteractionSnapshot;
  readOnly: boolean;
}

// An inert composition reference. The host owns attachment and current state.
// UI generation must tailor this to the supplied engineering job and bindings.
export default function App({ snapshot, readOnly }: AppProps) {
  return <ProcessUI>
    <Section title="Process status">
      {readOnly && <p>Preview — review the interface before using the process.</p>}
      <ProgressPanel state={snapshot.state} observations={snapshot.observations ?? []} />
      {(snapshot.diagnostics ?? []).map((reason, index) =>
        <ReasonNotice key={`${reason.code}-${index}`} reason={reason} />)}
    </Section>
    <Section title="Results and checks">
      {(snapshot.outputs ?? []).length === 0 && <p>Results will appear as the process produces them.</p>}
      {(snapshot.outputs ?? []).map(output => <ResultCard key={output.result_id} output={output} />)}
    </Section>
  </ProcessUI>;
}
